class Solution {
    public boolean isPowerOfThree(int n) {
        // If n is less than 1, it cannot be a power of three
        if (n < 1) {
            return false;
        }

        // Use logarithm to check if n is a power of three
        while (n % 3 == 0) {
            n /= 3;
        }

        // Return true if n equals to 1, otherwise return false
        return n == 1;
    }
}
```

