Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word in the file:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string filename, search_word;
    int count = 0;

    // Get input from user
    std::cout << "Enter the name of the file: ";
    std::cin >> filename;
    std::cout << "Enter the word to search for: ";
    std::cin >> search_word;

    // Open the file
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return 1;
    }

    // Read the file line by line
    std::string line;
    while (std::getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            count++;
            pos += search_word.length();
        }
    }

    // Close the file
    file.close();

    // Print the result
    std::cout << "The word '" << search_word << "' appears " << count << " times in the file." << std::endl;

    return 0;
}
```

